CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_approve_grn`(IN p_grn_id VARCHAR(36), IN p_user_id VARCHAR(36))
BEGIN
  DECLARE v_tenant_id VARCHAR(36);
  DECLARE v_product_id VARCHAR(36);
  DECLARE v_qty DECIMAL(15,4);
  DECLARE done INT DEFAULT 0;

  DECLARE cur CURSOR FOR
    SELECT tenant_id, product_id, qty
    FROM grn_items
    WHERE grn_id = p_grn_id;

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

  SELECT tenant_id INTO v_tenant_id FROM grn_headers WHERE id = p_grn_id;

  START TRANSACTION;

  OPEN cur;
  read_loop: LOOP
    FETCH cur INTO v_tenant_id, v_product_id, v_qty;
    IF done THEN LEAVE read_loop; END IF;

    INSERT INTO product_stocks (id, tenant_id, product_id, qty_on_hand, qty_reserved, qty_on_order)
      VALUES (UUID(), v_tenant_id, v_product_id, v_qty, 0, 0)
      ON DUPLICATE KEY UPDATE qty_on_hand = qty_on_hand + v_qty;
  END LOOP;
  CLOSE cur;

  UPDATE grn_headers
  SET status = 'approved',
      approved_by = p_user_id,
      approved_at = NOW()
  WHERE id = p_grn_id;

  COMMIT;
END ;;
DELIMITER ;
