  DECLARE done INT DEFAULT 0;

  DECLARE cur CURSOR FOR
    SELECT tenant_id, product_id, return_qty
    FROM grun_items
    WHERE grun_id = p_grun_id;

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

  SELECT tenant_id INTO v_tenant_id FROM grun_headers WHERE id = p_grun_id;

  START TRANSACTION;

  OPEN cur;
  read_loop: LOOP
    FETCH cur INTO v_tenant_id, v_product_id, v_return_qty;
    IF done THEN LEAVE read_loop; END IF;

    
    UPDATE product_stocks
    SET qty_on_hand = GREATEST(0, qty_on_hand - v_return_qty)
    WHERE tenant_id = v_tenant_id AND product_id = v_product_id;
  END LOOP;
  CLOSE cur;

  
  UPDATE grun_headers
  SET status = 'approved',
      approved_by = p_user_id,
      approved_at = NOW()
  WHERE id = p_grun_id;

  COMMIT;
END ;;
